import{_ as l,o as i,c as e,ag as o}from"./chunks/framework.D9ghT4bC.js";const b=JSON.parse('{"title":"UncivCN 更新日志","description":"","frontmatter":{"title":"UncivCN 更新日志"},"headers":[],"relativePath":"zh/UncivCN/Changelog.md","filePath":"zh/UncivCN/Changelog.md"}'),d={name:"zh/UncivCN/Changelog.md"};function t(r,a,u,n,c,h){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="uncivcn-更新日志" tabindex="-1">UncivCN 更新日志 <a class="header-anchor" href="#uncivcn-更新日志" aria-label="Permalink to &quot;UncivCN 更新日志&quot;">​</a></h1><p>版本号规则：上游版本 + CN 子版本号（<code>.1</code>、<code>.2</code>、<code>.3</code>…，同一上游版本可发多个 CN 子版本，如 4.20.8.1 → 4.20.8.4；跟进新上游后从 <code>.1</code> 重新开始，如 4.21.5 → 4.21.5.1）。</p><h2 id="未发布" tabindex="-1">未发布 <a class="header-anchor" href="#未发布" aria-label="Permalink to &quot;未发布&quot;">​</a></h2><ul><li>难度：国王及以上难度的 AI 不满修正改为 100/90/85/75（原 90/85/75/60），以实机数值为准</li><li>模组支持：单位血量上限可模组化——Units.json 新增 <code>maxHP</code> 字段（默认 100）+ 新 unique <code>[relativeAmount] Max HP</code>；残血减伤按血量百分比缩放，AI/UI 阈值全部相对化，Lua 的 <code>unit.getMaxHealth()</code> 返回动态上限</li><li>主菜单右下角按钮：Discord 改为 QQ 群入口（qm.qq.com），新增百度贴吧按钮，GitHub 按钮改指 CN 分支仓库；关于页仓库/更新日志/README 链接改指 UncivCN 分支（含版本锚点修正）</li><li>文档站链接按客户端语言自适应：简体/繁体中文客户端跳中文区（/zh/），其余语言跳英文区</li><li>CI：detekt / Docker 发布工作流改在 UncivCN 分支触发（此前绑定上游 master 分支从未运行），Release 判定只认 4 段版本号；移除上游 uncivbot 自动发版机器人（CN 为手动发版）</li><li>游戏内 wiki 链接改为 CN 文档站（club.unciv.cn），加载失败提示邮箱改为 <a href="mailto:hurxwork@qq.com" target="_blank" rel="noreferrer">hurxwork@qq.com</a></li><li>代码清理与审查修复：删除全项目审查发现的死代码与注释代码，修复 <code>ConditionalBuildingBuiltAll</code> 城市过滤失效、多段 <code>{A} {B}</code>/<code>non-[X]</code> 过滤恒错、<code>LongPriorityQueue.remove</code> 误删队首、<code>stateBasedRandom</code> 无头测试崩溃等问题</li><li>CI：修复 detekt 静态检查失败——更新配置中的弃用属性（移除 <code>OptionalWhenBraces</code>，<code>ForbiddenComment</code> 的 <code>values</code>/<code>customMessage</code> 改为 <code>comments</code>），并补齐 <code>UnitPresenter.kt</code> 文件末尾缺失的换行</li></ul><h2 id="_4-21-7-2-build-1252" tabindex="-1">4.21.7.2（build 1252） <a class="header-anchor" href="#_4-21-7-2-build-1252" aria-label="Permalink to &quot;4.21.7.2（build 1252）&quot;">​</a></h2><ul><li>Android：更新弹窗游戏内直接下载 APK（带进度），一键调起系统安装（FileProvider），自动引导「安装未知来源应用」授权</li><li>Android：下载断点救援（.part + 原子改名），「安装/重新下载」双按钮，复制一份到系统下载文件夹，自动清理旧安装包</li><li>主菜单「下载最新版本」改为列出当前平台安装包并直接下载所选包（不再跳转浏览器发布页）</li></ul><h2 id="_4-21-7-1-build-1251" tabindex="-1">4.21.7.1（build 1251） <a class="header-anchor" href="#_4-21-7-1-build-1251" aria-label="Permalink to &quot;4.21.7.1（build 1251）&quot;">​</a></h2><ul><li>合并上游 4.21.7 / 4.21.7-patch1 / patch2（41 个提交）：View 重构持续推进（#15280）、AI 战争逻辑修复、隐形轰炸机闪避、MP 平均回合用时、迷你地图 ANR 修复、Gradle 9.4.1 + LibGDX 1.14.2 + target SDK 36；CN 地图钉/单位钉与人口锁地适配新 View API</li><li>CI：修复 <code>unciv-lua-api</code> vsix 打包</li><li>模组工具：Lua API 定义随发版自动部署文档站，<code>unciv-lua-api</code> VSCode 扩展自动同步接入 LuaLS</li><li>文档：Lua API 与地图脚本参考改为 Kotlin 数据表驱动生成；工具链不再依赖 Python</li><li>Lua API：新增 <code>unit.getEraNumber()</code>、<code>civ.discoverTech()</code></li><li>模组：CoeHarMod 改为 git 子模块（独立仓库），规则经 Lua 精简</li></ul><h2 id="_4-21-6-6-build-1250" tabindex="-1">4.21.6.6（build 1250） <a class="header-anchor" href="#_4-21-6-6-build-1250" aria-label="Permalink to &quot;4.21.6.6（build 1250）&quot;">​</a></h2><ul><li>主菜单自动更新检测（镜像源回退）；「模组下载源」更名为「下载源」</li><li>修复自定义 Lua API 函数参数含函数调用表达式时的运行时崩溃</li><li>Lua API 大扩展（约 100 个新方法）、<code>ConditionalLuaCheck</code> unique、<code>TriggerUponTradeMade</code> 钩子</li><li>Lua 地图脚本：模组可在 <code>scripts/</code> 提供地图生成器，新增「Lua Generated」地图类型</li><li>Lua 沙箱加固；模组检查器覆盖地图脚本 API</li></ul><h2 id="_4-21-6-5-build-1249" tabindex="-1">4.21.6.5（build 1249） <a class="header-anchor" href="#_4-21-6-5-build-1249" aria-label="Permalink to &quot;4.21.6.5（build 1249）&quot;">​</a></h2><ul><li>文档：Lua 章节全面重写、EmmyLua 类型定义 + <code>LuaStarterMod</code> 模板、mod-ci 命令行</li><li>Lua 错误弹窗带行号；堵住 <code>package.loaded</code> 沙箱逃逸；指令预算阻止死循环卡死</li><li>新增：联机重开投票（房主开启、全员投票、超时默认同意、自动重开）</li><li>CI：Release 标题显式使用纯版本号</li></ul><h2 id="_4-21-6-4-build-1248" tabindex="-1">4.21.6.4（build 1248） <a class="header-anchor" href="#_4-21-6-4-build-1248" aria-label="Permalink to &quot;4.21.6.4（build 1248）&quot;">​</a></h2><ul><li>CI：Release 说明自动写入中英双语更新日志</li><li>新增「模组下载源」设置，支持国内镜像加速（gh-proxy/ghfast/ghproxy/自定义前缀）</li><li>开图界面：支持命名槽位保存/读取配置；剪贴板按钮移到右下角；「重置为默认」改为内置「默认配置」</li><li>文档：Coding-standards 新增发版检查清单与踩坑经验</li></ul><h2 id="_4-21-6-3-build-1247" tabindex="-1">4.21.6.3（build 1247） <a class="header-anchor" href="#_4-21-6-3-build-1247" aria-label="Permalink to &quot;4.21.6.3（build 1247）&quot;">​</a></h2><ul><li>修复 Docker 构建复制旧名 <code>Unciv.jar</code>；修复 Release 缺少 MSI 安装包</li></ul><h2 id="_4-21-6-2-build-1246" tabindex="-1">4.21.6.2（build 1246） <a class="header-anchor" href="#_4-21-6-2-build-1246" aria-label="Permalink to &quot;4.21.6.2（build 1246）&quot;">​</a></h2><ul><li>补齐 CN 自研功能缺失的简体中文翻译（47 个缺失 + 10 个空词条）</li></ul><h2 id="_4-21-6-1-build-1245" tabindex="-1">4.21.6.1（build 1245） <a class="header-anchor" href="#_4-21-6-1-build-1245" aria-label="Permalink to &quot;4.21.6.1（build 1245）&quot;">​</a></h2><ul><li>笔记改为按 gameId 存储，不再跨存档泄漏</li><li>地图钉/单位钉：长按/Alt+点击编辑、备注气泡、崩溃修复、中文词条补齐</li><li>ModOptions.json 新增 <code>modVersion</code> / <code>gameVersionRange</code> / <code>modDependencies</code></li><li>修复开图界面自定义尺寸重复行；内置规则集与上游对齐</li><li>合并上游 4.21.6（CPU 性能、AI 工人相邻加成、多人上传失败提示）</li><li>文档站链接修复（约 250 处锚点）；游戏内版本号构建时自动同步</li></ul><h2 id="_4-21-5-3-build-1244" tabindex="-1">4.21.5.3（build 1244） <a class="header-anchor" href="#_4-21-5-3-build-1244" aria-label="Permalink to &quot;4.21.5.3（build 1244）&quot;">​</a></h2><ul><li>修复 CI 测试失败（翻译模板缺空格、测试模组纳入版本库）</li><li>Deploy 不再推送 Discord 通知</li></ul><h2 id="_4-21-5-2-build-1243" tabindex="-1">4.21.5.2（build 1243） <a class="header-anchor" href="#_4-21-5-2-build-1243" aria-label="Permalink to &quot;4.21.5.2（build 1243）&quot;">​</a></h2><ul><li>官方 VitePress 文档站上线（中文全文搜索、中英一键切换）</li><li><code>docDescriptionZh</code>：unique 说明文档中文化</li><li>APK 签名本地化，产物统一命名 UncivCN</li></ul><h2 id="_4-21-5-1-build-1242" tabindex="-1">4.21.5.1（build 1242） <a class="header-anchor" href="#_4-21-5-1-build-1242" aria-label="Permalink to &quot;4.21.5.1（build 1242）&quot;">​</a></h2><ul><li>合并上游 4.21.5（AI 金币/战争逻辑修复、CPU 性能优化）</li><li>撤销自带 UCCC 模组；新增开图设置剪贴板导出/导入；人口锁地按钮调整；修复统计显示级联 bug</li></ul><h2 id="_4-21-0-2-2026-8-1" tabindex="-1">4.21.0.2（2026.8.1） <a class="header-anchor" href="#_4-21-0-2-2026-8-1" aria-label="Permalink to &quot;4.21.0.2（2026.8.1）&quot;">​</a></h2><ul><li>修复 UCCC 模组部分 bug</li></ul><h2 id="_4-21-0-1-2026-8-1" tabindex="-1">4.21.0.1（2026.8.1） <a class="header-anchor" href="#_4-21-0-1-2026-8-1" aria-label="Permalink to &quot;4.21.0.1（2026.8.1）&quot;">​</a></h2><ul><li>跟进上游近期更新（对称/镜像地图、统计面板）；补全中文本地化</li><li>联机默认服务器改为 <code>sp.unciv.cn:30123</code>；新增人口自动锁定按钮；自带 UCCC 模组</li><li>联机不再支持读档改变随机数</li></ul><h2 id="_4-20-17-2-2026-7-12" tabindex="-1">4.20.17.2（2026.7.12） <a class="header-anchor" href="#_4-20-17-2-2026-7-12" aria-label="Permalink to &quot;4.20.17.2（2026.7.12）&quot;">​</a></h2><ul><li>新增单位钉/地图钉；取消旋转对称地图半径奇偶限制；存档版本隔离；训练移民不再饿死市民</li></ul><h2 id="_4-20-17-1-2026-7-4" tabindex="-1">4.20.17.1（2026.7.4） <a class="header-anchor" href="#_4-20-17-1-2026-7-4" aria-label="Permalink to &quot;4.20.17.1（2026.7.4）&quot;">​</a></h2><ul><li>跟进上游一个多月的更新</li></ul><h2 id="_4-20-8-4-2026-5-26" tabindex="-1">4.20.8.4（2026.5.26） <a class="header-anchor" href="#_4-20-8-4-2026-5-26" aria-label="Permalink to &quot;4.20.8.4（2026.5.26）&quot;">​</a></h2><ul><li>模组检查器可筛查 Lua 错误；轮询联机显示在线状态</li></ul><h2 id="_4-20-8-3-2026-5-23" tabindex="-1">4.20.8.3（2026.5.23） <a class="header-anchor" href="#_4-20-8-3-2026-5-23" aria-label="Permalink to &quot;4.20.8.3（2026.5.23）&quot;">​</a></h2><ul><li>增强 Lua 系统；event 可挂载 Lua</li></ul><h2 id="_4-20-8-2-2026-5-22" tabindex="-1">4.20.8.2（2026.5.22） <a class="header-anchor" href="#_4-20-8-2-2026-5-22" aria-label="Permalink to &quot;4.20.8.2（2026.5.22）&quot;">​</a></h2><ul><li>模组支持 <a href="/Unciv/zh/Modders/Lua-Modding.html">Lua 脚本</a></li><li>修复「众神与国王」精英教育不送伟人；修复 TRY_INJECT 造价覆盖 bug</li><li>Amount 参数兼容 Countables</li></ul><h2 id="_4-20-8-1-2026-5-21" tabindex="-1">4.20.8.1（2026.5.21） <a class="header-anchor" href="#_4-20-8-1-2026-5-21" aria-label="Permalink to &quot;4.20.8.1（2026.5.21）&quot;">​</a></h2><ul><li>新增 <a href="./Polling-multiplayer.html">轮询联机功能</a></li></ul><h2 id="_4-20-7-4-2026-5-19" tabindex="-1">4.20.7.4（2026.5.19） <a class="header-anchor" href="#_4-20-7-4-2026-5-19" aria-label="Permalink to &quot;4.20.7.4（2026.5.19）&quot;">​</a></h2><ul><li>中心对称地图资源数量对称分布</li></ul><h2 id="_4-20-7-3-2026-5-19" tabindex="-1">4.20.7.3（2026.5.19） <a class="header-anchor" href="#_4-20-7-3-2026-5-19" aria-label="Permalink to &quot;4.20.7.3（2026.5.19）&quot;">​</a></h2><ul><li>扩展模组 JSON 系统，见 <a href="/Unciv/zh/Modders/Mod-file-structure/6-MergeActions.html">MergeAction 教程</a></li></ul><h2 id="_4-20-7-2" tabindex="-1">4.20.7.2 <a class="header-anchor" href="#_4-20-7-2" aria-label="Permalink to &quot;4.20.7.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.19</p><ul><li>安卓端安装包不再自带 CoeHarMod 模组</li><li>新增三种镜像地图模式（两瓣/三瓣/六瓣中心对称）</li></ul><h2 id="_4-20-6-3" tabindex="-1">4.20.6.3 <a class="header-anchor" href="#_4-20-6-3" aria-label="Permalink to &quot;4.20.6.3&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.17</p><ul><li>新增模组特性：</li></ul><table tabindex="0"><thead><tr><th>英文原文</th><th>中文释义</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>不再显示在城市面板中</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>可以在单个城市中重复建造[amount]次</td></tr></tbody></table><h2 id="_4-20-6-1" tabindex="-1">4.20.6.1 <a class="header-anchor" href="#_4-20-6-1" aria-label="Permalink to &quot;4.20.6.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.16</p><ul><li>同步两个月来上游更新</li><li>随机结果可变性收束为设置开关</li></ul><h2 id="_4-19-16-2" tabindex="-1">4.19.16.2 <a class="header-anchor" href="#_4-19-16-2" aria-label="Permalink to &quot;4.19.16.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.2</p><ul><li>远古遗迹随机结果可通过读档重载改变</li></ul><h2 id="_4-19-16-1" tabindex="-1">4.19.16.1 <a class="header-anchor" href="#_4-19-16-1" aria-label="Permalink to &quot;4.19.16.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.1</p><ul><li>城邦任务随机结果可通过读档重载改变</li></ul><h2 id="_4-19-15-cn2" tabindex="-1">4.19.15-cn2 <a class="header-anchor" href="#_4-19-15-cn2" aria-label="Permalink to &quot;4.19.15-cn2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.28</p><ul><li>新增范围攻击类模组特性（多目标、伤害随距离递减、自身/反击伤害）</li><li>统计面板数据导出 CSV</li></ul><h2 id="_4-19-15" tabindex="-1">4.19.15 <a class="header-anchor" href="#_4-19-15" aria-label="Permalink to &quot;4.19.15&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.26</p><ul><li>安卓端内置 <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod/和合共生</a></li><li>相邻城市可交换地块（需在 ModOptions.json 声明 &quot;Allow cities to claim tiles&quot;）</li></ul>',68)])])}const _=l(d,[["render",t]]);export{b as __pageData,_ as default};
